class Solution {
  public long maximumTotalSum(int[] maximumHeight) {
    java.util.Arrays.sort(maximumHeight);
    long sum = 0;
    int cur = Integer.MAX_VALUE;
    for (int i = maximumHeight.length - 1; i >= 0; i--) {
      cur = Math.min(maximumHeight[i], cur - 1);
      if (cur <= 0) return -1;
      sum += cur;
    }
    return sum;
  }
}
